def calc(expr: str) -> int | str:
    # Tokenizer
    import re

    TOKEN_REGEX = re.compile(r'\s*(?:(\d+)|(.))')
    # groups: 1 number, 2 any other char

    class Token:
        __slots__ = ('type', 'value')
        def __init__(self, typ, val=None):
            self.type = typ   # 'NUM', '+', '-', '*', '/', '%', '^', '(', ')', 'EOF'
            self.value = val

    def tokenize(s):
        pos = 0
        tokens = []
        while pos < len(s):
            m = TOKEN_REGEX.match(s, pos)
            if not m:
                break
            num, other = m.group(1), m.group(2)
            if num is not None:
                tokens.append(Token('NUM', int(num)))
            else:
                ch = other
                if ch in '+-*/%^()':
                    tokens.append(Token(ch))
                else:
                    # any other character shouldn't occur (input guaranteed valid)
                    pass
            pos = m.end()
        tokens.append(Token('EOF'))
        return tokens

    # Parser / Evaluator
    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0
            self.error = False

        def cur(self):
            return self.tokens[self.pos]

        def eat(self, typ=None):
            cur = self.cur()
            if typ and cur.type != typ:
                self.error = True
            else:
                self.pos += 1
            return cur

        # Helper arithmetic with error handling
        @staticmethod
        def trunc_div(a, b):
            if b == 0:
                raise ZeroDivisionError
            q = abs(a) // abs(b)
            return q if a * b >= 0 else -q

        @staticmethod
        def mod(a, b):
            if b == 0:
                raise ZeroDivisionError
            return a - b * Parser.trunc_div(a, b)

        # Grammar methods
        def parse(self):
            val = self.expr()
            if self.error or self.cur().type != 'EOF':
                return "error"
            return val

        # expr -> add
        def expr(self):
            return self.add()

        # add -> mul ((+|-) mul)*
        def add(self):
            left = self.mul()
            while self.cur().type in ('+', '-'):
                op = self.eat().type
                right = self.mul()
                if self.error:
                    return 0
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            return left

        # mul -> unary_expr ((*|/|%) unary_expr)*
        def mul(self):
            left = self.unary_expr()
            while self.cur().type in ('*', '/', '%'):
                op = self.eat().type
                right = self.unary_expr()
                if self.error:
                    return 0
                try:
                    if op == '*':
                        left = left * right
                    elif op == '/':
                        left = self.trunc_div(left, right)
                    else:  # '%'
                        left = self.mod(left, right)
                except ZeroDivisionError:
                    self.error = True
                    return 0
            return left

        # unary_expr -> '-' unary_expr | power
        def unary_expr(self):
            if self.cur().type == '-':
                self.eat('-')
                val = self.unary_expr()
                return -val
            else:
                return self.power()

        # power -> primary ('^' power)?
        def power(self):
            left = self.primary()
            if self.cur().type == '^':
                self.eat('^')
                right = self.power()          # right-associative
                if self.error:
                    return 0
                if right < 0:
                    self.error = True
                    return 0
                # Python pow handles big ints; 0**0 == 1 as required
                left = pow(left, right)
            return left

        # primary -> number | '(' expr ')'
        def primary(self):
            cur = self.cur()
            if cur.type == 'NUM':
                self.eat('NUM')
                return cur.value
            elif cur.type == '(':
                self.eat('(')
                val = self.expr()
                if self.cur().type != ')':
                    self.error = True
                else:
                    self.eat(')')
                return val
            else:
                # Should not happen for valid input
                self.error = True
                return 0

    try:
        tokens = tokenize(expr)
        parser = Parser(tokens)
        result = parser.parse()
        return result if not parser.error else "error"
    except Exception:
        # Any unexpected problem yields "error"
        return "error"
